  --font-size-6xl: 3rem;
  --font-size-7xl: 3.75rem;
  --font-size-8xl: 4.5rem;
  --font-size-9xl: 6rem;
  --font-size-10xl: 8rem;

  /* Font features */
  --font-feature-tabular: 'tnum';

  /* Content */
  --content-empty: '';

  /* Radii */
  --radius-xs: 0.125rem;
  --radius-sm: 0.25rem;
  --radius-md: 0.375rem;
  --radius-lg: 0.5rem;
  --radius-xl: 0.75rem;
  --radius-2xl: 1rem;
  --radius-3xl: 1.5rem;
  --radius-4xl: 2rem;

  /* Spacing */
  --spacing-4xs: 0.125rem;
  --spacing-3xs: 0.25rem;
  --spacing-2xs: 0.375rem;
  --spacing-xs: 0.5rem;
  --spacing-sm: 0.75rem;
