  /* Durations */
  --duration-fastest: 75ms;
  --duration-faster: 100ms;
  --duration-fast: 150ms;
  --duration-normal: 200ms;
  --duration-slow: 300ms;
  --duration-slower: 500ms;
  --duration-slowest: 800ms;

  /* Easings */
  --easing-smooth: cubic-bezier(.4, 0, .2, 1);
  --easing-soft: cubic-bezier(.33, 1, .68, 1);
  --easing-crisp: cubic-bezier(.16, 1, .3, 1);
