/* Static utilities for positioning, clipping, and content. */
@utilities {
  abs {
    position: absolute;
  }

  bg-clip-border {
    background-clip: border-box;
  }

  bg-clip-content {
    background-clip: content-box;
  }

  bg-clip-padding {
    background-clip: padding-box;
  }

  bg-clip-text {
    -webkit-background-clip: text;
            background-clip: text;
  }

  bg-origin-<border=border-box|content=content-box|padding=padding-box> {
    background-origin: --value();
  }

  block {
    display: block;
  }

  bottom {
    bottom: 0;
  }

  box-<border=border-box|content=content-box> {
    box-sizing: --value();
  }

  break-spaces {
    white-space: break-spaces;
  }

  break-word {
    word-break: break-word;
  }

  capitalize {
    text-transform: capitalize;
  }

  center {
    left: 0;
    right: 0;
    margin-left: auto;
    margin-right: auto;
  }

  clip-border {
    clip-path: border-box;
  }

  clip-content {
    clip-path: content-box;
  }

  clip-fill {
    clip-path: fill-box;
  }

  clip-margin {
    clip-path: margin-box;
  }

  clip-none {
    clip-path: none;
  }

  clip-padding {
    clip-path: padding-box;
  }

  clip-stroke {
    clip-path: stroke-box;
  }

  clip-view {
    clip-path: view-box;
  }

  container {
    container-type: inline-size;
  }

  content-<around=space-around|between=space-between|evenly=space-evenly> {
    align-content: --value();
  }

  content-<baseline|center|end|flex-end|flex-start|normal|start|stretch> {
    align-content: --value();
  }

  contents {
    display: contents;
